// What the dispatch and pause scripts share: arguments, the digest repo, `gh api`, and the
// discovery of the repos attached to the session, and the check that each can be
// pushed to.
import { execFileSync } from "node:child_process";
import { existsSync, readdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { isDigest, marked } from "./decide.ts";
import type { GhIssue } from "./github.ts";

export const FOOTER =
  "\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_";
export const PAUSE_LABEL = "workshop-paused";
export const SNAPSHOT = "<!-- workshop-snapshot -->";
export const RESUMED = "<!-- workshop-resumed -->";

export function arg(name: string): string | undefined;
export function arg(name: string, dflt: string | number): string;
export function arg(name: string, dflt?: string | number) {
  const i = process.argv.indexOf(name);
  return i > 0 ? process.argv[i + 1] : dflt === undefined ? undefined : String(dflt);
}
export const flag = (name: string) => process.argv.includes(name);

export const run = (cmd: string, args: string[], input?: string): string =>
  execFileSync(cmd, args, {
    encoding: "utf8",
    input,
    maxBuffer: 1 << 26,
    // Keep stderr out of the log: a failure still throws with it attached,
    // and an expected 422 stays quiet.
    stdio: ["pipe", "pipe", "pipe"],
  });
export const api = <T = any>(path: string, ...rest: string[]): T =>
  JSON.parse(run("gh", ["api", path, ...rest]) || "null");
// --paginate --slurp yields one array per page.
export const all = <T = any>(path: string): T[] =>
  api<T[][]>(path, "--paginate", "--slurp").flat();
export const post = (path: string, body: unknown, method = "POST") =>
  run("gh", ["api", "-X", method, path, "--input", "-"], JSON.stringify(body));
export const names = (x: { labels: (string | { name: string })[] }): string[] =>
  x.labels.map((l) => (typeof l === "string" ? l : l.name));

/**
 * The workshop config: `{digest, checkouts, repos: [{repo, name, path}]}`. `--digest
 * owner/repo` names the repo holding the digest issue; SKILL.md says which. The repos are every GitHub clone directly under checkouts, which is `--checkouts`,
 * $WORKSHOP_CHECKOUTS, or the folder holding the clone the run started in (the
 * working directory itself when that isn't a clone): the repos attached to the
 * session. `--repos a/b,c/d` limits the run to some of them.
 */
export type Item = {
  repo: string;
  ref: string;
  url: string;
  title: string;
  why?: string;
  ask?: string;
  waiting?: boolean; // Not picked up, but only counted in the digest
  issue?: number;
  pr?: number;
  created?: string;
  // What the workshop board shows; the digest ignores them.
  kind?: "issue" | "pr";
  tier?: "haiku" | "sonnet" | "opus";
  check?: "green" | "red" | "pending";
  automerge?: boolean;
  linkedPrs?: number[]; // the PRs an issue's step waits on
  sub?: "decide" | "afterMerge" | "goAhead" | "blocked"; // why an issue waits
};
export type Repo = { repo: string; name: string; path: string };

export const loadConfig = (): { digest: string; checkouts: string; repos: Repo[] } => {
  const digest = arg("--digest");
  if (!digest || !/^[^/\s]+\/[^/\s]+$/.test(digest))
    throw new Error("pass --digest owner/repo: the dispatcher's SKILL.md names the digest repo");
  return { digest, ...attachedRepos() };
};

// The checkouts folder and the repos under it, as loadConfig describes; the survey
// chooser reads them the same way.
export const attachedRepos = (): { checkouts: string; repos: Repo[] } => {
  const checkouts = resolve(
    arg("--checkouts") ?? process.env.WORKSHOP_CHECKOUTS ?? startedIn(),
  );
  const found = readdirSync(checkouts, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(checkouts, d.name, ".git")))
    .map((d): Repo | null => {
      const path = join(checkouts, d.name);
      let url: string;
      try {
        url = run("git", ["-C", path, "remote", "get-url", "origin"]);
      } catch {
        return null;
      }
      const repo = url.trim().match(/github\.com[/:]([^/]+\/[^/]+?)(?:\.git)?\/?$/i)?.[1];
      return repo ? { repo, name: repo.split("/")[1], path } : null;
    })
    .filter((r) => r !== null)
    .sort((a, b) => a.repo.localeCompare(b.repo));
  const only = arg("--repos")?.split(",").map((r) => r.trim().toLowerCase());
  const repos = found.filter((r) => !only || only.includes(r.repo.toLowerCase()));
  const unknown = (only ?? []).filter((o) => !repos.some((r) => r.repo.toLowerCase() === o));
  if (unknown.length)
    throw new Error(
      `--repos names repos not checked out under ${checkouts}: ${unknown.join(", ")}. Attach them to the session.`,
    );
  if (!repos.length)
    throw new Error(`No GitHub clone under ${checkouts}: attach a repo to the session.`);
  return { checkouts, repos };
};

// The folder holding the clone the run started in, or the working directory itself
// when the run didn't start in a clone (a session with several repos may start
// above them).
const startedIn = () => {
  try {
    return dirname(run("git", ["rev-parse", "--show-toplevel"]).trim());
  } catch {
    return process.cwd();
  }
};

/**
 * The attached repos that can't be pushed to, each with its reason. A dry-run
 * push writes nothing.
 */
export const unpushable = (repos: Repo[]) => {
  const out: { repo: string; reason: string }[] = [];
  for (const r of repos) {
    try {
      run("git", [
        "-C",
        r.path,
        "push",
        "--dry-run",
        "--quiet",
        "origin",
        "HEAD:refs/heads/claude/workshop-push-check",
      ]);
    } catch (e) {
      const err = e as { stderr?: Buffer | string; message: string };
      out.push({
        repo: r.repo,
        reason: `can't push (${(err.stderr || err.message).toString().trim().split("\n").at(-1)})`,
      });
    }
  }
  return out;
};

/**
 * Stops the run, naming every attached repo that can't be pushed to. For a script
 * that has nothing to say about a repo it can't write to (`pause.ts`).
 */
export const preflight = (repos: Repo[]) => {
  const problems = unpushable(repos).map((u) => `${u.repo}: ${u.reason}`);
  if (problems.length)
    throw new Error(
      `The workshop can't run on every attached repo:\n- ${problems.join("\n- ")}\nGive the session push access to the repo, or detach it.`,
    );
};


// normal: nothing to do. drain: the label is on a digest and the snapshot isn't
// posted yet. paused: the snapshot is posted. resume: the label is gone and the
// snapshot has no "resumed" comment after it.
export type PauseState = "normal" | "drain" | "paused" | "resume";

/**
 * The workshop's pause state, read from the open digests: the label on either one,
 * the marker comments on the newest (the draft). `digest` is that newest issue and
 * `snap` the latest snapshot comment on it; both are undefined when there is no digest.
 */
export const readPause = (DIGEST: string) => {
  const digests = all<GhIssue>(`repos/${DIGEST}/issues?state=open&per_page=100`)
    .filter((i) => !i.pull_request && isDigest(i.title))
    .sort((a, b) => a.number - b.number);
  const digest = digests.at(-1);
  if (!digest) return { state: "normal" as PauseState };
  const labelled = digests.find((d) => names(d).includes(PAUSE_LABEL));
  const comments = all<{ body: string; created_at: string; html_url?: string }>(
    `repos/${DIGEST}/issues/${digest.number}/comments?per_page=100`,
  );
  const snap = comments.findLast((c) => marked(c, SNAPSHOT));
  const labeledAt = labelled
    ? all<{ event: string; label: { name: string }; created_at: string }>(
        `repos/${DIGEST}/issues/${labelled.number}/events?per_page=100`,
      ).findLast((e) => e.event === "labeled" && e.label.name === PAUSE_LABEL)?.created_at
    : null;
  const resumed = snap && comments.some((c) => marked(c, RESUMED) && c.created_at > snap.created_at);
  const state: PauseState = labelled
    ? snap && labeledAt && snap.created_at > labeledAt
      ? "paused"
      : "drain"
    : snap && !resumed
      ? "resume"
      : "normal";
  return { state, digest, snap };
};

// Runs main(), turning a thrown error into one clear line and exit code 1.
export const main = (fn: () => void) => {
  try {
    fn();
  } catch (e) {
    console.error(`workshop: ${(e as Error).message}`);
    process.exit(1);
  }
};
